// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // current owner is address(0) in a freshly deployed C; initiate handover from it
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.acceptOwnership();
        assertTrue(c.owner() == newOwner);
    }
}
